    """Split a single CSV line into fields.

    Fields may be wrapped in double quotes.  Inside a quoted field, commas
    are literal and a doubled quote ("") represents one quote character.
    The surrounding quotes are stripped from the resulting value.
    """
    # Drop a trailing line terminator, if present.
    if line.endswith('\n'):
        line = line[:-1]
        if line.endswith('\r'):
            line = line[:-1]

    fields = []
    cur = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                cur.append(ch)
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                fields.append(''.join(cur))
                cur = []
            else:
                cur.append(ch)
        i += 1

    fields.append(''.join(cur))
    return fields
